export interface PostMeta {
  title: string;
  date: string;
  tags: string[];
  draft: boolean;
}

export interface Post extends PostMeta {
  slug: string;
  html: string;
  raw: string;
}

export interface TagPage {
  tag: string;
  posts: Post[];
  html: string;
}

export interface SiteData {
  posts: Post[];
  tags: TagPage[];
  rss: string;
}

import { readFileSync, readdirSync, statSync, writeFileSync, mkdirSync, copyFileSync, existsSync } from "node:fs";
import { join, dirname, relative, basename, extname } from "node:path";
import matter from "gray-matter";
import { Marked } from "marked";
import { markedHighlight } from "marked-highlight";
import hljs from "highlight.js";
import Handlebars from "handlebars";
import type { Post, PostMeta, TagPage, SiteData } from "./types.js";

const marked = new Marked(
  markedHighlight({
    langPrefix: "hljs language-",
    highlight(code: string, lang: string) {
      if (lang && hljs.getLanguage(lang)) {
        return hljs.highlight(code, { language: lang }).value;
      }
      return hljs.highlightAuto(code).value;
    },
  })
);

function slugify(name: string): string {
  return basename(name, extname(name));
}

function parseFile(path: string): Post | null {
  const raw = readFileSync(path, "utf-8");
  const { data, content } = matter(raw);
  const meta = data as Partial<PostMeta>;
  if (meta.draft) return null;
  const title = meta.title ?? slugify(path);
  const date = meta.date ?? "";
  const tags = meta.tags ?? [];
  const html = marked.parse(content) as string;
  return { title, date: String(date), tags: Array.isArray(tags) ? tags : [tags].filter(Boolean), draft: !!meta.draft, slug: slugify(path), html, raw: content };
}

function collectFiles(dir: string): string[] {
  const result: string[] = [];
  function walk(d: string) {
    for (const entry of readdirSync(d)) {
      const full = join(d, entry);
      const s = statSync(full);
      if (s.isDirectory()) { walk(full); }
      else if (entry.endsWith(".md")) { result.push(full); }
    }
  }
  walk(dir);
  return result;
}

export function build(sourceDir: string, templateDir: string, outputDir: string): SiteData {
  const files = collectFiles(sourceDir);
  const posts: Post[] = [];
  for (const f of files) {
    const p = parseFile(f);
    if (p) posts.push(p);
  }
  posts.sort((a, b) => (b.date || "").localeCompare(a.date || ""));

  Handlebars.registerHelper("formatDate", (d: string) => {
    try { return new Date(d).toISOString().slice(0, 10); } catch { return d; }
  });

  const partials: Record<string, string> = {};
  const partialsDir = join(templateDir, "partials");
  if (existsSync(partialsDir)) {
    for (const f of readdirSync(partialsDir)) {
      if (f.endsWith(".hbs") || f.endsWith(".handlebars")) {
        partials[basename(f, extname(f))] = readFileSync(join(partialsDir, f), "utf-8");
      }
    }
  }

  for (const [name, src] of Object.entries(partials)) {
    Handlebars.registerPartial(name, src);
  }

  const layoutSrc = readFileSync(join(templateDir, "layout.hbs"), "utf-8");
  const layout = Handlebars.compile(layoutSrc);

  const postTemplate = existsSync(join(templateDir, "post.hbs"))
    ? Handlebars.compile(readFileSync(join(templateDir, "post.hbs"), "utf-8"))
    : null;

  const indexTemplate = existsSync(join(templateDir, "index.hbs"))
    ? Handlebars.compile(readFileSync(join(templateDir, "index.hbs"), "utf-8"))
    : null;

  const tagTemplate = existsSync(join(templateDir, "tag.hbs"))
    ? Handlebars.compile(readFileSync(join(templateDir, "tag.hbs"), "utf-8"))
    : null;

  if (!existsSync(outputDir)) mkdirSync(outputDir, { recursive: true });

  const tagMap = new Map<string, Post[]>();
  for (const post of posts) {
    for (const tag of post.tags) {
      if (!tagMap.has(tag)) tagMap.set(tag, []);
      tagMap.get(tag)!.push(post);
    }
  }

  const tagPages: TagPage[] = [];

  for (const [tag, tagPosts] of tagMap) {
    let tagHtml = "";
    if (tagTemplate) {
      tagHtml = tagTemplate({ tag, posts: tagPosts, allPosts: posts, allTags: [...tagMap.keys()].sort() });
    }
    const pageContent = layout({ content: tagHtml, title: `Tag: ${tag}`, posts, tags: [...tagMap.keys()].sort(), tag, tagPosts });
    const tagDir = join(outputDir, "tags", tag);
    mkdirSync(tagDir, { recursive: true });
    writeFileSync(join(tagDir, "index.html"), pageContent);
    tagPages.push({ tag, posts: tagPosts, html: pageContent });
  }

  if (indexTemplate) {
    const indexContent = indexTemplate({ posts, tags: [...tagMap.keys()].sort() });
    const indexPage = layout({ content: indexContent, title: "Home", posts, tags: [...tagMap.keys()].sort() });
    writeFileSync(join(outputDir, "index.html"), indexPage);
  }

  for (const post of posts) {
    let body = "";
    if (postTemplate) {
      body = postTemplate({ post, posts, tags: [post.tags], ...post });
    } else {
      body = post.html;
    }
    const html = layout({ content: body, title: post.title, post, posts, tags: [...tagMap.keys()].sort() });
    const outPath = join(outputDir, post.slug, "index.html");
    mkdirSync(dirname(outPath), { recursive: true });
    writeFileSync(outPath, html);
  }

  const assetsDir = join(templateDir, "assets");
  if (existsSync(assetsDir)) {
    copyAssets(assetsDir, outputDir);
  }

  const rss = buildRss(posts);
  writeFileSync(join(outputDir, "feed.xml"), rss);

  return { posts, tags: tagPages, rss };
}

function copyAssets(src: string, dest: string) {
  for (const entry of readdirSync(src)) {
    const srcPath = join(src, entry);
    const destPath = join(dest, relative(src, srcPath));
    if (statSync(srcPath).isDirectory()) {
      if (!existsSync(destPath)) mkdirSync(destPath, { recursive: true });
      copyAssets(srcPath, destPath);
    } else {
      mkdirSync(dirname(destPath), { recursive: true });
      copyFileSync(srcPath, destPath);
    }
  }
}

function buildRss(posts: Post[]): string {
  const items = posts.map(p => {
    const date = p.date ? new Date(p.date).toUTCString() : new Date().toUTCString();
    return `    <item>
      <title><![CDATA[${p.title}]]></title>
      <link>/${p.slug}/</link>
      <guid isPermaLink="true">/${p.slug}/</guid>
      <pubDate>${date}</pubDate>
      <description><![CDATA[${p.html.slice(0, 500)}]]></description>
    </item>`;
  }).join("\n");

  return `<?xml version="1.0" encoding="UTF-8"?>
<rss version="2.0" xmlns:atom="http://www.w3.org/2005/Atom">
  <channel>
    <title>Site</title>
    <link>/</link>
    <description>Generated static site</description>
    <language>en</language>
    <lastBuildDate>${new Date().toUTCString()}</lastBuildDate>
    <atom:link href="/feed.xml" rel="self" type="application/rss+xml"/>
${items}
  </channel>
</rss>`;
}

import { createServer, type IncomingMessage, type ServerResponse } from "node:http";
import { readFileSync, existsSync, watch } from "node:fs";
import { join, extname } from "node:path";
import { WebSocketServer, WebSocket } from "ws";
import { build } from "./ssg.js";

const RELOAD_SCRIPT = `
<script>
(function() {
  var ws = new WebSocket('ws://' + location.host + '/__reload');
  ws.onmessage = function(e) {
    if (e.data === 'reload') location.reload();
  };
  ws.onclose = function() {
    setTimeout(function() {
      new WebSocket('ws://' + location.host + '/__reload');
    }, 1000);
  };
})();
</script>`;

const MIME: Record<string, string> = {
  ".html": "text/html",
  ".css": "text/css",
  ".js": "application/javascript",
  ".json": "application/json",
  ".png": "image/png",
  ".jpg": "image/jpeg",
  ".svg": "image/svg+xml",
  ".ico": "image/x-icon",
  ".xml": "application/xml",
};

function serveFile(path: string, res: ServerResponse, injectReload: boolean) {
  if (!existsSync(path)) return false;
  let content = readFileSync(path);
  const ext = extname(path);
  const mime = MIME[ext] ?? "application/octet-stream";
  if (injectReload && mime === "text/html") {
    const s = content.toString("utf-8");
    // Insert reload script before </body>
    content = Buffer.from(s.replace("</body>", RELOAD_SCRIPT + "</body>"));
  }
  res.writeHead(200, { "Content-Type": mime, "Cache-Control": "no-cache" });
  res.end(content);
  return true;
}

export function serve(outputDir: string, sourceDir: string, templateDir: string, port: number) {
  const wss = new WebSocketServer({ noServer: true });
  const sockets = new Set<WebSocket>();

  wss.on("connection", (ws) => {
    sockets.add(ws);
    ws.on("close", () => sockets.delete(ws));
  });

  function reload() {
    for (const ws of sockets) {
      ws.send("reload");
    }
  }

  function rebuild() {
    try {
      build(sourceDir, templateDir, outputDir);
      console.log("  [rebuilt]");
      reload();
    } catch (e) {
      console.error("  [build error]", e);
    }
  }

  const watcher = watch(sourceDir, { recursive: true }, (event, filename) => {
    if (filename?.endsWith(".md")) {
      console.log(`  [${event}] ${filename}`);
      rebuild();
    }
  });

  const templateWatcher = watch(templateDir, { recursive: true }, () => {
    console.log("  [template change]");
    rebuild();
  });

  const httpServer = createServer((req: IncomingMessage, res: ServerResponse) => {
    const url = new URL(req.url ?? "/", `http://localhost:${port}`);
    let pathname = url.pathname;

    if (pathname === "/__reload") {
      // handled by upgrade
      res.writeHead(404);
      res.end();
      return;
    }

    if (pathname === "/") pathname = "/index.html";
    let filePath = join(outputDir, pathname);

    if (!existsSync(filePath)) {
      // try index.html in directory
      if (!extname(pathname)) {
        filePath = join(outputDir, pathname, "index.html");
      }
    }

    if (serveFile(filePath, res, true)) return;
    res.writeHead(404);
    res.end("Not found");
  });

  httpServer.on("upgrade", (req, socket, head) => {
    const url = new URL(req.url ?? "/", `http://localhost:${port}`);
    if (url.pathname === "/__reload") {
      wss.handleUpgrade(req, socket, head, (ws) => {
        wss.emit("connection", ws, req);
      });
    } else {
      socket.destroy();
    }
  });

  httpServer.listen(port, () => {
    console.log(`  Dev server at http://localhost:${port}`);
  });

  return { httpServer, watcher, templateWatcher, wss, rebuild };
}

#!/usr/bin/env node
import { existsSync } from "node:fs";
import { resolve } from "node:path";
import { build } from "./ssg.js";
import { serve } from "./server.js";

function parseArgs(args: string[]) {
  const opts: Record<string, string | boolean> = {};
  for (let i = 2; i < args.length; i++) {
    const a = args[i];
    if (a === "--source" || a === "-s") { opts.source = args[++i]; }
    else if (a === "--templates" || a === "-t") { opts.templates = args[++i]; }
    else if (a === "--output" || a === "-o") { opts.output = args[++i]; }
    else if (a === "--port" || a === "-p") { opts.port = args[++i]; }
    else if (a === "--serve" || a === "-S") { opts.serve = true; }
    else if (a === "--help" || a === "-h") { opts.help = true; }
    else if (a.startsWith("--")) { opts[a.slice(2)] = args[i + 1]?.startsWith("-") ? true : args[++i]; }
  }
  return opts;
}

function showHelp() {
  console.log(`
Usage: ssg [options]

Options:
  -s, --source <dir>      Source directory of Markdown files (default: ./content)
  -t, --templates <dir>   Template directory of Handlebars templates (default: ./templates)
  -o, --output <dir>      Output directory for generated HTML (default: ./dist)
  -S, --serve             Start dev server after build
  -p, --port <port>       Dev server port (default: 3000)
  -h, --help              Show this help
`);
}

async function main() {
  const opts = parseArgs(process.argv);

  if (opts.help) { showHelp(); process.exit(0); }

  const sourceDir = resolve(String(opts.source ?? "content"));
  const templateDir = resolve(String(opts.templates ?? "templates"));
  const outputDir = resolve(String(opts.output ?? "dist"));
  const port = parseInt(String(opts.port ?? "3000"), 10);

  if (!existsSync(sourceDir)) { console.error(`Source directory not found: ${sourceDir}`); process.exit(1); }
  if (!existsSync(templateDir)) { console.error(`Template directory not found: ${templateDir}`); process.exit(1); }

  console.log("Building site...");
  const result = build(sourceDir, templateDir, outputDir);
  console.log(`  ${result.posts.length} posts, ${result.tags.length} tag pages`);
  console.log("Site built to", outputDir);

  if (opts.serve) {
    serve(outputDir, sourceDir, templateDir, port);
  }
}

main().catch(e => { console.error(e); process.exit(1); });

